1	<!doctype html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Two Pizzas</title>
7	<style>
8	  :root {
9	    color-scheme: light dark;
10	    --bg: #fff7ec;
11	    --ink: #3a2412;
12	    --crust-outer: #c8852a;
13	    --crust-inner: #f5c073;
14	    --sauce: #c0341a;
15	    --cheese: #ffd766;
16	    --pepperoni: #a8201a;
17	    --pepperoni-shade: #6b1411;
18	    --basil: #2f7a2a;
19	    --basil-shade: #1f4f1d;
20	    --mozz: #fff8e7;
21	    --mozz-shade: #f0e0b8;
22	  }
23	  @media (prefers-color-scheme: dark) {
24	    :root { --bg: #1c140c; --ink: #f6e8d0; }
25	  }
26	
27	  * { box-sizing: border-box; }
28	
29	  html, body { margin: 0; padding: 0; }
30	
31	  body {
32	    background: var(--bg);
33	    color: var(--ink);
34	    font: 16px/1.4 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
35	    min-height: 100vh;
36	    display: flex;
37	    flex-direction: column;
38	    align-items: center;
39	    padding: 2rem 1rem 3rem;
40	  }
41	
42	  h1 {
43	    margin: 0 0 0.25rem;
44	    font-size: clamp(1.5rem, 4vw, 2.25rem);
45	    letter-spacing: 0.02em;
46	  }
47	
48	  p.lede {
49	    margin: 0 0 2rem;
50	    opacity: 0.75;
51	    text-align: center;
52	    max-width: 40ch;
53	  }
54	
55	  .pizzas {
56	    display: grid;
57	    grid-template-columns: repeat(2, minmax(0, 1fr));
58	    gap: clamp(1rem, 4vw, 3rem);
59	    width: 100%;
60	    max-width: 900px;
61	    justify-items: center;
62	  }
63	  @media (max-width: 640px) {
64	    .pizzas { grid-template-columns: 1fr; }
65	  }
66	
67	  figure {
68	    margin: 0;
69	    display: flex;
70	    flex-direction: column;
71	    align-items: center;
72	    gap: 0.75rem;
73	  }
74	
75	  figcaption {
76	    font-weight: 600;
77	    letter-spacing: 0.04em;
78	    text-transform: uppercase;
79	    font-size: 0.85rem;
80	  }
81	
82	  .pizza {
83	    --size: min(70vw, 360px);
84	    width: var(--size);
85	    height: var(--size);
86	    border-radius: 50%;
87	    position: relative;
88	    background:
89	      radial-gradient(circle at 50% 50%,
90	        var(--cheese) 0 60%,
91	        var(--sauce) 60% 86%,
92	        var(--crust-inner) 86% 92%,
93	        var(--crust-outer) 92% 100%);
94	    box-shadow:
95	      0 12px 28px rgba(0, 0, 0, 0.18),
96	      inset 0 0 0 2px rgba(0, 0, 0, 0.05);
97	  }
98	
99	  /* Subtle baked texture on the crust */
100	  .pizza::before {
101	    content: "";
102	    position: absolute;
103	    inset: 0;
104	    border-radius: 50%;
105	    background:
106	      radial-gradient(circle at 20% 25%, rgba(0,0,0,0.08) 0 4px, transparent 5px),
107	      radial-gradient(circle at 80% 30%, rgba(0,0,0,0.08) 0 3px, transparent 4px),
108	      radial-gradient(circle at 30% 80%, rgba(0,0,0,0.08) 0 5px, transparent 6px),
109	      radial-gradient(circle at 75% 78%, rgba(0,0,0,0.08) 0 4px, transparent 5px);
110	    pointer-events: none;
111	  }
112	
113	  /* Toppings layer */
114	  .topping {
115	    position: absolute;
116	    border-radius: 50%;
117	    transform: translate(-50%, -50%);
118	  }
119	
120	  /* --- Pepperoni pizza --- */
121	  .pep {
122	    width: 14%;
123	    height: 14%;
124	    background:
125	      radial-gradient(circle at 35% 35%,
126	        var(--pepperoni) 0 60%,
127	        var(--pepperoni-shade) 100%);
128	    box-shadow:
129	      inset 0 0 0 1px rgba(0,0,0,0.15),
130	      0 1px 2px rgba(0,0,0,0.25);
131	  }
132	  .pep::after {
133	    content: "";
134	    position: absolute;
135	    inset: 22% 22% 22% 22%;
136	    border-radius: 50%;
137	    background:
138	      radial-gradient(circle at 30% 30%,
139	        rgba(255,255,255,0.18) 0 30%,
140	        transparent 60%);
141	  }
142	
143	  /* --- Margherita pizza --- */
144	  .mozz {
145	    width: 16%;
146	    height: 12%;
147	    background:
148	      radial-gradient(ellipse at 35% 30%,
149	        var(--mozz) 0 65%,
150	        var(--mozz-shade) 100%);
151	    box-shadow: inset 0 0 0 1px rgba(0,0,0,0.07);
152	  }
153	
154	  .basil {
155	    width: 9%;
156	    height: 11%;
157	    background:
158	      radial-gradient(ellipse at 50% 40%,
159	        var(--basil) 0 60%,
160	        var(--basil-shade) 100%);
161	    border-radius: 60% 60% 60% 60% / 80% 80% 40% 40%;
162	    box-shadow: inset 0 -2px 0 rgba(0,0,0,0.18);
163	  }
164	  .basil::before {
165	    content: "";
166	    position: absolute;
167	    left: 50%;
168	    top: 8%;
169	    width: 6%;
170	    height: 80%;
171	    background: rgba(0,0,0,0.18);
172	    transform: translateX(-50%);
173	  }
174	
175	  footer {
176	    margin-top: 2.5rem;
177	    font-size: 0.8rem;
178	    opacity: 0.55;
179	  }
180	</style>
181	</head>
182	<body>
183	  <h1>Two Pizzas</h1>
184	  <p class="lede">A self-contained HTML page — no external assets, just CSS.</p>
185	
186	  <div class="pizzas">
187	    <figure aria-label="Pepperoni pizza">
188	      <div class="pizza" role="img" aria-label="Pepperoni pizza illustration">
189	        <span class="topping pep" style="left:35%;top:30%"></span>
190	        <span class="topping pep" style="left:62%;top:28%"></span>
191	        <span class="topping pep" style="left:50%;top:48%"></span>
192	        <span class="topping pep" style="left:30%;top:58%"></span>
193	        <span class="topping pep" style="left:68%;top:60%"></span>
194	        <span class="topping pep" style="left:42%;top:72%"></span>
195	        <span class="topping pep" style="left:60%;top:78%"></span>
196	      </div>
197	      <figcaption>Pepperoni</figcaption>
198	    </figure>
199	
200	    <figure aria-label="Margherita pizza">
201	      <div class="pizza" role="img" aria-label="Margherita pizza illustration">
202	        <span class="topping mozz" style="left:36%;top:32%"></span>
203	        <span class="topping mozz" style="left:60%;top:30%"></span>
204	        <span class="topping mozz" style="left:50%;top:50%"></span>
205	        <span class="topping mozz" style="left:32%;top:62%"></span>
206	        <span class="topping mozz" style="left:66%;top:64%"></span>
207	        <span class="topping mozz" style="left:48%;top:76%"></span>
208	
209	        <span class="topping basil" style="left:46%;top:38%"></span>
210	        <span class="topping basil" style="left:58%;top:56%;transform:translate(-50%,-50%) rotate(35deg)"></span>
211	        <span class="topping basil" style="left:38%;top:54%;transform:translate(-50%,-50%) rotate(-25deg)"></span>
212	        <span class="topping basil" style="left:55%;top:72%;transform:translate(-50%,-50%) rotate(15deg)"></span>
213	      </div>
214	      <figcaption>Margherita</figcaption>
215	    </figure>
216	  </div>
217	
218	  <footer>Open this file directly in a browser — no server required.</footer>
219	</body>
220	</html>
